"""
Pydantic Schemas for the Gemini AI Agent Engine.
"""

from typing import Any, Dict, List, Optional
from pydantic import BaseModel, Field, field_validator


class InventoryInsightsResponse(BaseModel):
    """Structured executive inventory insights generated by Gemini AI."""
    summary: str = Field(
        ...,
        description="High-level operational overview of current inventory health for the retail owner",
    )
    critical_alerts: List[str] = Field(
        default_factory=list,
        description="Priority alerts for out-of-stock and critically low products",
    )
    reorder_advice: str = Field(
        ...,
        description="Contextual business explanation of the deterministic reorder recommendations",
    )
    overstock_advice: Optional[str] = Field(
        default=None,
        description="Actionable guidance on handling overstocked items and releasing capital",
    )
    action_items: List[str] = Field(
        default_factory=list,
        description="Top prioritized operational recommendations for the shop owner today",
    )


class AgentQueryRequest(BaseModel):
    """Natural language inventory inquiry payload."""
    query: str = Field(
        ...,
        min_length=2,
        max_length=500,
        description="Natural language question about inventory, stock, or reorder targets",
    )
    category: Optional[str] = Field(
        default=None,
        description="Optional product category filter to narrow analysis scope",
    )

    @field_validator("query", mode="before")
    @classmethod
    def validate_query(cls, v: Any) -> str:
        if isinstance(v, str):
            v_stripped = v.strip()
            if len(v_stripped) < 2:
                raise ValueError("Query must contain at least 2 non-whitespace characters")
            return v_stripped
        return v


class AgentQueryResponse(BaseModel):
    """Structured response to a natural language inventory inquiry."""
    answer: str = Field(
        ...,
        description="Concise answer grounded strictly in ground-truth inventory data",
    )
    relevant_skus: List[str] = Field(
        default_factory=list,
        description="SKUs of products directly referenced in the explanation",
    )
    referenced_metrics: Dict[str, Any] = Field(
        default_factory=dict,
        description="Key metrics referenced (e.g., total_units, estimated_cost, item counts)",
    )
    suggested_followups: List[str] = Field(
        default_factory=list,
        description="2-3 relevant follow-up questions the store owner may want to ask next",
    )
